   110	pub(crate) async fn run(
   111	    handlers: &[ConfiguredHandler],
   112	    shell: &CommandShell,
   113	    output_spiller: &HookOutputSpiller,
   114	    request: SessionStartRequest,
   115	    turn_id: Option<String>,
   116	) -> SessionStartOutcome {
   117	    let session_id = request.session_id;
   118	    let matched = dispatcher::select_handlers(
   119	        handlers,
   120	        request.target.event_name(),
   121	        Some(request.target.matcher_input()),
   122	    );
   123	    if matched.is_empty() {
   124	        return SessionStartOutcome {
   125	            hook_events: Vec::new(),
   126	            should_stop: false,
   127	            stop_reason: None,
   128	            additional_contexts: Vec::new(),
   129	        };
   130	    }
   131	
   132	    let (input_json, turn_id) = match request.target {
   133	        StartHookTarget::SessionStart { source } => {
   134	            let input_json = match serde_json::to_string(&SessionStartCommandInput::new(
   135	                request.session_id.to_string(),
   136	                request.transcript_path.clone(),
   137	                request.cwd.display().to_string(),
   138	                request.model.clone(),
   139	                request.permission_mode.clone(),
   140	                source.as_str().to_string(),
   141	            )) {
   142	                Ok(input_json) => input_json,
   143	                Err(error) => {
   144	                    return serialization_failure_outcome(
   145	                        common::serialization_failure_hook_events(
   146	                            matched,
   147	                            turn_id,
   148	                            format!("failed to serialize session start hook input: {error}"),
   149	                        ),
   150	                    );
   151	                }
   152	            };
   153	            (input_json, turn_id)
   154	        }
   155	        StartHookTarget::SubagentStart {
   156	            turn_id: subagent_turn_id,
   157	            agent_id,
   158	            agent_type,
   159	        } => {
   160	            let input = SubagentStartCommandInput {
   161	                session_id: request.session_id.to_string(),
   162	                turn_id: subagent_turn_id.clone(),
   163	                transcript_path: NullableString::from_path(request.transcript_path.clone()),
   164	                cwd: request.cwd.display().to_string(),
   165	                hook_event_name: "SubagentStart".to_string(),
   166	                model: request.model.clone(),
   167	                permission_mode: request.permission_mode.clone(),
   168	                agent_id,
   169	                agent_type,
   170	            };
   171	            let input_json = match serde_json::to_string(&input) {
   172	                Ok(input_json) => input_json,
   173	                Err(error) => {
   174	                    return serialization_failure_outcome(
   175	                        common::serialization_failure_hook_events(
   176	                            matched,
   177	                            Some(subagent_turn_id),
   178	                            format!("failed to serialize subagent start hook input: {error}"),
   179	                        ),
   180	                    );
   181	                }
   182	            };
   183	            (input_json, Some(subagent_turn_id))
   184	        }
   185	    };
   186	
   187	    let results = dispatcher::execute_handlers(
   188	        shell,
   189	        matched,
   190	        input_json,
   191	        request.cwd.as_path(),
   192	        turn_id,
   193	        parse_completed,
   194	    )
   195	    .await;
   196	
   197	    let should_stop = results.iter().any(|result| result.data.should_stop);
   198	    let stop_reason = results
   199	        .iter()
   200	        .find_map(|result| result.data.stop_reason.clone());
   201	    let additional_contexts = common::flatten_additional_contexts(
   202	        results
   203	            .iter()
   204	            .map(|result| result.data.additional_contexts_for_model.as_slice()),
   205	    );
   206	    let additional_contexts = output_spiller
   207	        .maybe_spill_additional_contexts(session_id, additional_contexts)
   208	        .await;
   209	
   210	    SessionStartOutcome {
   211	        hook_events: results.into_iter().map(|result| result.completed).collect(),
   212	        should_stop,
   213	        stop_reason,
   214	        additional_contexts,
   215	    }
   216	}
